"""Generate fixed MACD references using independent Python float64 operations."""

from __future__ import annotations

import hashlib
import json
import math
import struct
from pathlib import Path

CASES = (
    (
        "carried_line",
        (1, 3, 3, 1, 1),
        (-0.0, 1.0, 3.0, None, math.nan, 2.0, 6.0, None, 5.0, -1.0, 8.0, 0.0),
    ),
    (
        "independent_warmups",
        (1, 2, 1, 5, 3),
        (-2.0, 1.0, 4.0, 2.0, None, 5.0, 6.0, 1.0, math.nan, 3.0, 7.0, 0.0),
    ),
    (
        "nonfinite",
        (1, 3, 3, 1, 1),
        (-1e308, 1e308, None, 1.0, -math.inf, None, math.inf, 2.0, math.nan, 0.0),
    ),
    (
        "large_spans",
        (2**63 + 1, 2**64 - 1, 2**63, 1, 2),
        (-0.0, 1.0, 2.0, None, -1.0, 3.0, math.nan, 5.0),
    ),
    (
        "default",
        (12, 26, 9, 1, 1),
        (None, math.nan, 2.0, 5.0, 1.0, -3.0, None, 4.0, 8.0, 2.0),
    ),
)


def ewma(
    state: tuple[int, float], sample: float | None, span: int
) -> tuple[int, float]:
    count, previous = state
    if sample is None or math.isnan(sample):
        return state
    count += 1
    alpha = 2.0 / (float(span) + 1.0)
    if count == 1 or alpha == 1.0:
        return count, sample
    difference = sample - previous
    increment = alpha * difference
    return count, previous + increment


def reference(
    parameters: tuple[int, ...], prices: tuple[float | None, ...]
) -> list[list[float | None]]:
    fast_span, slow_span, signal_span, minimum, signal_minimum = parameters
    fast = slow = signal = (0, 0.0)
    rows = []
    for price in prices:
        fast = ewma(fast, price, fast_span)
        slow = ewma(slow, price, slow_span)
        line = fast[1] - slow[1] if fast[0] >= minimum and slow[0] >= minimum else None
        signal = ewma(signal, line, signal_span)
        signal_value = signal[1] if signal[0] >= signal_minimum else None
        histogram = (
            line - signal_value
            if line is not None and signal_value is not None
            else None
        )
        rows.append([line, signal_value, histogram])
    return rows


def option(value: float | None) -> str:
    if value is None:
        return "None"
    bits = struct.unpack("<Q", struct.pack("<d", value))[0]
    literal = f"{bits:_d}"
    assert int(literal.replace("_", "")) == bits
    return f"Some({literal})"


def rust_array(values: list[str], indent: str) -> str:
    inline = "[" + ", ".join(values) + "]"
    if "\n" not in inline and len(inline) <= 60:
        return inline
    body = "\n".join(f"{indent}    {value}," for value in values)
    return f"[\n{body}\n{indent}]"


def source() -> str:
    lines = [
        "// Generated by the independent stdlib float64 reference in generate.py.",
        "// Finite/signed-zero results are exact; "
        "generated NaN payloads are classified.",
        "pub struct Fixture {",
        "    pub name: &'static str,",
        "    pub parameters: [u64; 5],",
        "    pub input: &'static [Option<u64>],",
        "    pub expected: &'static [[Option<u64>; 3]],",
        "}",
        "pub const FIXTURES: &[Fixture] = &[",
    ]
    for name, parameters, prices in CASES:
        parameters_text = rust_array(
            [f"{value:_d}" for value in parameters], "        "
        )
        inputs = rust_array([option(value) for value in prices], "        ")
        rows = [
            rust_array([option(value) for value in row], "            ")
            for row in reference(parameters, prices)
        ]
        lines.extend(
            [
                "    Fixture {",
                f'        name: "{name}",',
                f"        parameters: {parameters_text},",
                f"        input: &{inputs},",
                f"        expected: &{rust_array(rows, '        ')},",
                "    },",
            ]
        )
    lines.append("];")
    return "\n".join(lines) + "\n"


def main() -> None:
    directory = Path(__file__).resolve().parent
    golden = directory / "golden.rs"
    golden.write_bytes(source().encode("utf-8"))
    provenance = {
        "reference": "independent stdlib Python float64; no production/TA imports",
        "cases": [
            {"name": name, "parameters": parameters, "rows": len(prices)}
            for name, parameters, prices in CASES
        ],
        "semantics": (
            "three first-valid seeded, unadjusted EWMA recurrences; "
            "carried lines update signal; only null/NaN skip"
        ),
        "comparison": (
            "validity and finite/signed-zero bits exact; generated NaN classification"
        ),
        "golden_sha256": hashlib.sha256(golden.read_bytes()).hexdigest(),
    }
    (directory / "provenance.json").write_bytes(
        (json.dumps(provenance, sort_keys=True, indent=2) + "\n").encode("utf-8")
    )


if __name__ == "__main__":
    main()
